#define SUBDIVS 10.0
#define SUBDIV_ITERS 4
#define SUBDIV_FRACTAL 3.02
#define DENSITY 1.0
#define ANIM_AMP 1.0

#define FATNESS 0.9
#define SLIMNES 0.22

#define GRID_ALPHA 0.0
#define POINTS_ALPHA 0.0

// Utility Methods

float rand(vec2 v) {
 return fract(sin(dot(v, vec2(12.345, 67.890)))*123456.0);
}

vec2 rand2(vec2 v) {
 return vec2(rand(v), rand(v+12.345));
}

// Debug Tools

float border(vec2 v, float thickness) {
    return (v.x <= thickness ? 1.0 : 0.0)
         + (v.y <= thickness ? 1.0 : 0.0);
}

float point(vec2 v, float radius) {
    return length(v) <= radius ? 1.0 : 0.0;
}

// Foam

vec2 randomPointInCell(vec2 cell, float subdivs) {
    vec2 rt = rand2(cell);
    vec2 anim = (vec2(sin(iTime*rt.x-rt.y), sin(iTime*rt.y-rt.x))+1.0)/2.0;
    anim = (anim*ANIM_AMP)+(1.0-ANIM_AMP)/2.0;
    return (cell + anim)/subdivs;
}

float edge(vec2 uv, vec2 rand_pt, vec2 cell, float subdivs, float density, int depth) {
    if (rand(cell) > DENSITY) {
        return 0.0;
    }

    // Get neighbor cell's point
    vec2 point = randomPointInCell(cell, subdivs);

    // Project uv on the edge between this cell and the neighbor
    vec2 dir_cell = point - rand_pt;
    vec2 dir_uv = uv - rand_pt;
    float proj_l = dot(dir_uv, dir_cell)/(length(dir_cell)*length(dir_cell));

    float dmax = 0.1/subdivs;
    float foam = 0.0;

    float d = length(uv-point);
    foam += FATNESS/(subdivs*d);

    // Round tip
    if (proj_l < 0.0) {
        foam += dmax/length(uv-rand_pt);
    }
    // Edge
    else {
        vec2 proj = rand_pt + dir_cell*proj_l;
        float d = length(uv-proj);
        foam += dmax/d;
    }

    return foam;
}

float foam(vec2 uv, vec2 uv_floor, float subdivs, float density, int depth) {   

    vec2 rt = rand2(uv_floor);
    uv = uv + 0.02*vec2(sin(iTime*rt.x), cos(iTime*rt.y));

    // Generate random point on grid
    vec2 rand_pt = randomPointInCell(uv_floor, subdivs);

    // Render foam edges
    float v = 0.0;
    if (rand(uv_floor) <= density) {
        float max_f = 0.0;

        vec2 cell = vec2(uv_floor.x+1.0,uv_floor.y+0.0);
        float f = edge(uv, rand_pt, cell, subdivs, density, depth);        
        max_f = max(f, max_f);

        cell = vec2(uv_floor.x-1.0,uv_floor.y+0.0);
        f = edge(uv, rand_pt, cell, subdivs, density, depth);
        max_f = max(f, max_f);

        cell = vec2(uv_floor.x+0.0,uv_floor.y+1.0);
        f = edge(uv, rand_pt, cell, subdivs, density, depth);
        max_f = max(f, max_f);

        cell = vec2(uv_floor.x+0.0,uv_floor.y-1.0);
        f = edge(uv, rand_pt, cell, subdivs, density, depth);
        max_f = max(f, max_f);


        float d = length(uv-rand_pt);
        max_f += FATNESS/(subdivs*d);

        v = max_f*SLIMNES;
    }
    v = (clamp(v,0.4,1.0)-0.4)/0.6;
    return v;
}

float makeFoam(vec2 uv, float density)
{
    // Rotate by 45 degrees, it looks better this way
    uv = mat2(0.7071, 0.7071,
             -0.7071, 0.7071)*uv;

    float v = 1.0;
    for (int i = 0; i < SUBDIV_ITERS; i++) {  
        float subdivs = SUBDIVS*((SUBDIV_FRACTAL-float(i))/SUBDIV_FRACTAL);

        // Split space into a grid
        vec2 uv_floor = floor(uv*subdivs);
        vec2 uv_fract = fract(uv*subdivs);

        // Render point and foam edges
        float f = foam(uv, uv_floor, subdivs, density, 1);
        v *= f*f;

        uv = uv_floor+uv_fract;
    }

    return v;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.y;

    // Sea palette
    vec3 c1 = vec3(0.078, 0.313, 0.313);
    vec3 c2 = vec3(0.156, 0.313, 0.313);
    vec3 c3 = vec3(0.156, 0.392, 0.392);

    // Density Oscilation

    float t_osc = iTime * 1.0;
    float k_osc = 20.0;

    float y = uv.y
        + 0.01*sin(k_osc*0.9*uv.x - 0.3*t_osc)        // wiggle x
        + 0.01*sin(k_osc*0.8*uv.x + 0.3*t_osc - 0.1)  // wiggle x opposite
        + 0.05*sin(k_osc*0.5*uv.y + 0.5*t_osc);       // back and forth at y


    float wl_mask = exp(-(y*4.0)*(y*4.0));
    float amp_mask = exp(-(2.0*y-1.2)*(2.0*y-1.2));

    float v = sin(k_osc*y + t_osc - wl_mask*8.0);

    v = (v+1.0)/2.0;
    v *= amp_mask;
    v = pow(v,2.0);


    vec3 base_color = vec3(0.078+0.078*v, 0.313+0.099*v, 0.313+0.099*v);
    //vec3 base_color = vec3(v,v,v);


    // Foam

    float foam_y = uv.y
        + 0.03*sin(k_osc*0.65*uv.x - 0.14*t_osc)        // wiggle x
        + 0.05*sin(k_osc*0.43*uv.x + 0.29*t_osc - 0.12)  // wiggle x opposite
        + 0.01*sin(k_osc*1.45*uv.x + 0.18*t_osc - 0.44)  // wiggle x
        + 0.02*sin(k_osc*1.33*uv.x - 0.27*t_osc - 0.54)  // wiggle x opposite
        + 0.05*sin(k_osc*1.2*uv.y + 0.5*t_osc);       // back and forth at y

    wl_mask = exp(-(y*9.0-0.0)*(y*9.0-0.0));
    amp_mask = exp(-(2.0*y-0.9)*(2.0*y-0.9));

    float foam_v = 1.0-fract(k_osc*0.2*foam_y + t_osc*0.12);
    foam_v *= amp_mask;

    float x = foam_v;
    foam_v = clamp(1.0-100.0*x*x,0.0,1.0)+clamp(1.0-1.2*(x-1.0)*(x-1.0),0.0,1.0);

    foam_v = pow(foam_v,5.0);

    vec2 foam_uv = uv + vec2(0, 0.006*t_osc);
    float foam = makeFoam(foam_uv, 0.8*DENSITY) * foam_v;

    base_color += foam * 3.0;
    //base_color = vec3(foam_v,foam_v,foam_v);

    // Grain

    float grain = makeFoam(foam_uv, 1.0*DENSITY);

    //base_color=vec3(grain,grain,grain);

    base_color += vec3(0.3,1.0,1.0)*grain*0.05;

    // Output to screen
    fragColor = vec4(base_color,1.0);
}
